record Point(int x, int y) {}   // constructor, accessors, equals/hashCode/toString all generated

sealed interface Shape permits Circle, Square {}
record Circle(double radius) implements Shape {}
record Square(double side) implements Shape {}

public class ModernJava {
    static double area(Shape shape) {
        return switch (shape) {
            case Circle c -> Math.PI * c.radius() * c.radius();
            case Square s -> s.side() * s.side();
            // no default needed — the compiler knows these are the ONLY permitted subtypes
        };
    }

    public static void main(String[] args) {
        Point p = new Point(1, 2);
        System.out.println(p);                 // Point[x=1, y=2] — generated toString()
        System.out.println(area(new Circle(2)));
    }
}
